// C4 date-wise SIMULATED HISTORICAL REPLAY, NIFTY only, the latest 15 completed sessions (owner, 2026-10-24). Research only.
// Rule unchanged: fakeUpPaperCore.isPaperSignal on fakeMoveGrid.run events (5-min, NIFTY step 50). Costs = corrected
// standard (c4Audit model B = final1560/strategy.optionPnl, conservative: +0.5 %/side slippage AND 1-minute delay).
// Signals are generated by run() over the full loaded history, which only uses data up to each candle (owner S/R from
// earlier sessions, the 4-bar window, the touch before the signal); outcomes use the 60 minutes after the entry.
// Usage: npx tsx c4Nifty15.ts   (writes the md and the two CSVs next to this file)
import fs from "fs";
import path from "path";
import { DayData } from "../../nifty20/data";
import { run } from "../fakeMoveGrid";
import { isPaperSignal } from "../fakeUpPaperCore";
import { load } from "../final1560/dataAudit";
import { prepareIndex } from "../final1560/backtest";
import { optionPnl } from "../final1560/strategy";

const LOT = 75, STEP = 50, N = 15, REACH = [15, 20, 30, 45, 60];
const hm = (t: number) => new Date((t + 19800) * 1000).toISOString().slice(11, 16), r2 = (v: number) => Math.round(v * 100) / 100;
const slipC = (p: number) => Math.max(0.5, 0.0025 * p) + 0.005 * p;

const days = load("NIFTY"), ds = days.filter((d) => d.spot.size >= 300), last = ds.slice(-N).map((d) => d.day), Pp = prepareIndex("NIFTY");
interface T { day: string; n: number; entry: string; exit: string; strike: number; lvl: number; px: number; stop: number; target: number; reason: string;
  premIn: number | null; premOut: number | null; gross: number | null; brokerage: number | null; statutory: number | null; slippage: number | null; net: number | null; netBase: number | null;
  mfe: number; reach: Record<number, boolean>; invalidated: string }
const trades: T[] = [];
for (const e of run(days as DayData[], 5, STEP).ev) {
  if (!last.includes(e.day) || !isPaperSignal(e as any, "2000-01-01")) continue;
  const d = Math.max(e.stop - e.px, 0.25 * e.atr), stop = e.px + d, target = e.px - d, tOut = e.r0.tOut ?? e.t;
  const mins = [...ds.find((x) => x.day === e.day)!.spot.entries()].sort((a, b) => a[0] - b[0]).filter(([t]) => t >= e.t && t < e.t + 3600);
  // index reach in the PE direction on 1-min closes, from entry until the first close at/above the stop (invalidation) or 60 min
  let mfe = 0, inv = "not within 60 min";
  for (const [t, p] of mins) { if (p >= stop) { inv = hm(t + 60); break; } mfe = Math.max(mfe, e.px - p); }
  const di = Pp.ds.findIndex((x) => x.day === e.day), key = `${e.atm}PE`;
  const c0 = Pp.premAt(di, key, e.t + 60), c1 = Pp.premAt(di, key, tOut + 120), b0 = Pp.premAt(di, key, e.t), b1 = Pp.premAt(di, key, tOut + 60);
  const ok = c0 != null && c1 != null;
  trades.push({ day: e.day, n: 0, entry: hm(e.t), exit: hm(tOut + 60), strike: e.atm, lvl: e.lvl, px: e.px, stop, target,
    reason: e.r0.win ? "TARGET" : e.r0.loss ? "STOP" : "TIME", premIn: c0, premOut: c1,
    gross: ok ? (c1! - c0!) * LOT : null, brokerage: ok ? 40 : null, statutory: ok ? (0.001 * c1! + 0.0004 * (c0! + c1!)) * LOT : null,
    slippage: ok ? (slipC(c0!) + slipC(c1!)) * LOT : null, net: ok ? optionPnl(c0!, c1!, LOT, true).net : null,
    netBase: b0 != null && b1 != null ? optionPnl(b0, b1, LOT).net : null, mfe, reach: Object.fromEntries(REACH.map((x) => [x, mfe >= x])), invalidated: inv });
}
trades.sort((a, b) => (a.day + a.entry).localeCompare(b.day + b.entry));
// reconciliation: the cost breakdown must add back to optionPnl's conservative net
for (const t of trades) if (t.net != null && Math.abs(t.gross! - t.brokerage! - t.statutory! - t.slippage! - t.net) > 0.01) throw new Error(`cost breakdown mismatch ${t.day} ${t.entry}`);

interface D { day: string; signals: number; priced: number; unavailable: number; win: number; loss: number; time: number; gross: number; brokerage: number; statutory: number; slippage: number; net: number; cum: number; dayDD: number; cumDD: number }
const daily: D[] = []; let cum = 0, peak = 0, maxDD = 0;
for (const day of last) {
  const ts = trades.filter((t) => t.day === day); ts.forEach((t, i) => (t.n = i + 1));
  const p = ts.filter((t) => t.net != null), sum = (f: (t: T) => number) => p.reduce((a, t) => a + f(t), 0);
  let c = 0, pk = 0, dd = 0; for (const t of p) { c += t.net!; pk = Math.max(pk, c); dd = Math.max(dd, pk - c); cum += t.net!; peak = Math.max(peak, cum); maxDD = Math.max(maxDD, peak - cum); }
  daily.push({ day, signals: ts.length, priced: p.length, unavailable: ts.length - p.length, win: p.filter((t) => t.net! > 0).length, loss: p.filter((t) => t.net! <= 0).length,
    time: ts.filter((t) => t.reason === "TIME").length, gross: sum((t) => t.gross!), brokerage: sum((t) => t.brokerage!), statutory: sum((t) => t.statutory!), slippage: sum((t) => t.slippage!),
    net: sum((t) => t.net!), cum, dayDD: dd, cumDD: maxDD });
}
// reconcile the daily file against the trade file
const tradeNet = trades.filter((t) => t.net != null).reduce((a, t) => a + t.net!, 0), dayNet = daily.reduce((a, d) => a + d.net, 0);
if (Math.abs(tradeNet - dayNet) > 0.01 || daily.reduce((a, d) => a + d.signals, 0) !== trades.length) throw new Error("daily vs trade reconciliation failed");

const dir = __dirname, f = (v: number | null) => (v == null ? "UNAVAILABLE" : r2(v).toFixed(2));
fs.writeFileSync(path.join(dir, "c4_nifty_last_15_sessions_trades.csv"),
  ["label,date,trade_no,entry_time,exit_time,pe_strike,owner_level,entry_index,stop_index,target_index,exit_reason,entry_premium,exit_premium,gross_pnl,brokerage,statutory,slippage,net_pnl_conservative,net_pnl_base,mfe_before_invalidation_pts," + REACH.map((x) => `reach_${x}`).join(",") + ",invalidated_at"]
    .concat(trades.map((t) => ["SIMULATED_REPLAY", t.day, t.n, t.entry, t.exit, t.strike, r2(t.lvl), r2(t.px), r2(t.stop), r2(t.target), t.reason, f(t.premIn), f(t.premOut), f(t.gross), f(t.brokerage), f(t.statutory), f(t.slippage), f(t.net), f(t.netBase), r2(t.mfe), ...REACH.map((x) => (t.reach[x] ? "YES" : "NO")), t.invalidated].join(","))).join("\n") + "\n");
fs.writeFileSync(path.join(dir, "c4_nifty_last_15_sessions_daily.csv"),
  ["label,date,signals,trades_priced,trades_unavailable,wins,losses,time_exits,gross_pnl,brokerage,statutory,slippage,net_pnl_conservative,cumulative_net,day_max_drawdown,cumulative_max_drawdown"]
    .concat(daily.map((d) => ["SIMULATED_REPLAY", d.day, d.signals, d.priced, d.unavailable, d.win, d.loss, d.time, f(d.gross), f(d.brokerage), f(d.statutory), f(d.slippage), f(d.net), f(d.cum), f(d.dayDD), f(d.cumDD)].join(","))).join("\n") + "\n");

const R = (v: number) => Math.round(v).toLocaleString("en-IN"), priced = trades.filter((t) => t.net != null);
const best = daily.reduce((a, d) => (d.net > a.net ? d : a)), worst = daily.reduce((a, d) => (d.net < a.net ? d : a));
const o: string[] = [];
o.push("# C4 — NIFTY, latest 15 sessions: SIMULATED HISTORICAL REPLAY", "",
  "> **This is a simulated replay of historical data, not live paper-trading performance.** No live paper record exists before 2026-10-26.", "",
  `Sessions: ${last[0]} → ${last[last.length - 1]} (${last.length} completed NIFTY sessions in the ProTrader data). Generated by \`c4Nifty15.ts\`.`, "",
  "**Rule (unchanged):** `fakeUpPaperCore.isPaperSignal` on `fakeMoveGrid.run` events — 5-min FAKE-UP confirmed at an OWNER S/R level, call writing (ATM CE OI ↑ and CE premium ↓ over the 4-bar window), level touched ≥ 30 min earlier. Buy the ATM PE. Index stop = 4-bar high (at least 0.25 × ATR above entry), target 1 : 1 below, 60-minute time exit, on 1-min closes.", "",
  "**Costs (the corrected standard of the latest C4 audit, conservative variant):** 1 lot = 75. Fills 1 minute after the signal and after the index exit (the 1-min close of that minute, at most 2 minutes old, else UNAVAILABLE). Brokerage ₹40 per round trip; statutory 0.1 % of sell value + 0.04 % of turnover; slippage max(₹0.5, 0.25 %) + 0.5 % per side. Base net (no delay, 0.25 % slippage) is in the trade CSV for reference.", "",
  "**Reach:** largest favourable index move (points down) on 1-min closes from entry until the first close at or above the stop, within 60 minutes. It is measured independently of the 1 : 1 exit, so a trade can reach +30 after its target was already taken.", "",
  "## Daily", "", "| Date | Signals | W / L / Time exits | Gross ₹ | Brokerage ₹ | Statutory ₹ | Slippage ₹ | Net (cons.) ₹ | Cumulative ₹ | Day max DD ₹ |", "|---|---|---|---|---|---|---|---|---|---|");
for (const d of daily) o.push(`| ${d.day} | ${d.signals}${d.unavailable ? ` (${d.unavailable} unavailable)` : ""} | ${d.signals ? `${d.win} / ${d.loss} / ${d.time}` : "—"} | ${R(d.gross)} | ${R(d.brokerage)} | ${R(d.statutory)} | ${R(d.slippage)} | ${R(d.net)} | ${R(d.cum)} | ${R(d.dayDD)} |`);
o.push("", "W / L = net after all costs > 0 / ≤ 0. Time exits are counted separately by exit reason (a time exit is also a W or an L).", "", "## Trades", "",
  "| Date | # | Entry | Exit | Reason | PE | Premium in → out | Index entry | Stop | Target | Gross ₹ | Costs ₹ | Net ₹ | MFE pts | +15 / +20 / +30 / +45 / +60 |", "|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|");
for (const t of trades) o.push(`| ${t.day} | ${t.n} | ${t.entry} | ${t.exit} | ${t.reason} | ${t.strike} | ${f(t.premIn)} → ${f(t.premOut)} | ${t.px.toFixed(1)} | ${t.stop.toFixed(1)} | ${t.target.toFixed(1)} | ${t.gross == null ? "UNAVAILABLE" : R(t.gross)} | ${t.net == null ? "—" : R(t.brokerage! + t.statutory! + t.slippage!)} | ${t.net == null ? "UNAVAILABLE" : R(t.net)} | ${t.mfe.toFixed(1)} | ${REACH.map((x) => (t.reach[x] ? "✓" : "✗")).join(" ")} |`);
if (!trades.length) o.push("| — | | | | | | | | | | | | | | |");
o.push("", "## Summary (15 sessions)", "",
  `- Total net P&L (conservative, after all costs): **₹${R(dayNet)}**`,
  `- Days: ${daily.filter((d) => d.priced && d.net > 0).length} profitable · ${daily.filter((d) => d.priced && d.net <= 0).length} losing · ${daily.filter((d) => !d.signals).length} with zero signals`,
  `- Trades: ${trades.length} signals, ${priced.length} priced, ${trades.length - priced.length} unavailable · net win rate ${priced.length ? ((priced.filter((t) => t.net! > 0).length / priced.length) * 100).toFixed(1) : "—"} % (${priced.filter((t) => t.net! > 0).length} of ${priced.length})`,
  `- Exit reasons: ${["TARGET", "STOP", "TIME"].map((r) => `${r} ${trades.filter((t) => t.reason === r).length}`).join(" · ")}`,
  `- Average net per trade: ${priced.length ? `₹${R(dayNet / priced.length)}` : "—"}`,
  `- Largest daily profit: ₹${R(best.net)} (${best.day}) · largest daily loss: ₹${R(worst.net)} (${worst.day})`,
  `- Maximum cumulative drawdown: ₹${R(maxDD)}`,
  `- Reach before invalidation: ${REACH.map((x) => `+${x} ${trades.filter((t) => t.reach[x]).length}/${trades.length}`).join(" · ")}`, "",
  `Reconciliation: the sum of the ${priced.length} trade nets in the trade CSV (₹${r2(tradeNet).toFixed(2)}) equals the sum of the daily nets (₹${r2(dayNet).toFixed(2)}); every trade's gross − brokerage − statutory − slippage equals optionPnl's conservative net to ₹0.01.`, "",
  "Sample warning: 15 sessions is far too few to judge the rule; this is a date-wise look, not evidence of an edge.");
fs.writeFileSync(path.join(dir, "C4_NIFTY_LAST_15_SESSIONS.md"), o.join("\n") + "\n");
console.log(o.join("\n"));
process.exit(0);
